int
uvmcowalloc(pagetable_t pagetable, uint64 va)
{
  uint64 pa;
  pte_t *pte;
  uint flags;

  if (va >= MAXVA) return -1;

  va = PGROUNDDOWN(va);
  pte = walk(pagetable, va, 0);
  if (pte == 0) return -1;

  pa = PTE2PA(*pte);
  if (pa == 0) return -1;

  flags = PTE_FLAGS(*pte);
  if (flags & PTE_COW){  
    flags = (flags & ~PTE_COW) | PTE_W;
    char *ka = kalloc();
    if (ka == 0) return -1;
    memmove(ka, (char*)pa, PGSIZE);
    kfree((void*)pa);
    *pte = PA2PTE((uint64)ka) | flags;
    return 0;
  }

  return 0;
}
