		pa = PTE2PA(*pte);
		flags = PTE_FLAGS(*pte);
		if(mappages(kvm, i, PGSIZE, pa, flags&(~PTE_U)) != 0){
			panic("procuvmcopy: remap");
			goto err;
		}
	}
	return 0;

err:
	uvmunmap(kvm, 0, i / PGSIZE, 1);
	return -1; 
}
