```c++
int
growproc(int n)
{
  uint sz;
  struct proc *p = myproc();

  sz = p->sz;
  if(n > 0){
  	// check the virtual address is no more than 0x0c000000L
  	if((sz + n) >= PLIC){
	  return -1;
	}
	// malloc 
    if((sz = uvmalloc(p->pagetable, sz, sz + n)) == 0) {
      return -1;
    }
	// mapper user page to kernel page table
	if((procuvmcopy(p->pagetable, p->kpagetable, p->sz, sz)) < 0){
	   return -1;
	}
