    sz = uvmdealloc(p->pagetable, sz, sz + n);
	// remove all the pages from the kernel table
	uvmunmap(p->kpagetable,PGROUNDUP(sz),(PGROUNDUP(p->sz)-PGROUNDUP(sz))/PGSIZE,0);
  }
  p->sz = sz;
  return 0;
}
