  // 判断当前的trap类型
  if(r_scause() == 8){// 系统调用
    // system call

    if(p->killed)
      exit(-1);

    // sepc points to the ecall instruction,
    // but we want to return to the next instruction.
    // 如果为系统调用，则将恢复的PC指向它的下一个指令
    p->trapframe->epc += 4;

