  regs[E1000_TDLEN] = sizeof(tx_ring);
  regs[E1000_TDH] = regs[E1000_TDT] = 0;

  // [E1000 14.4] Receive initialization
  // 初始化接收队列
  memset(rx_ring, 0, sizeof(rx_ring));
