#### 地址
https://leetcode.cn/contest/weekly-contest-333/problems/minimum-operations-to-reduce-an-integer-to-0/
#### 题意
    广度优先搜索
#### 思路
1. 应该有贪心思路的解法的，结果全部都弄成了暴力的广度优先搜索和深度优先搜索，题目就变得非常简单了，直接暴力搜索即可。
2. 复杂度分析：
+ 时间复杂度：$O(n \log n)$，其中 $n$ 为数组的长度。
+ 空间复杂度：$O(n)$，主要为排序需要空间。

#### 代码

```C++
class Solution {
public:
    int minOperations(int n) {
        int len = 32 - __builtin_clz(n);
        int lower = 0, upper = 1 << len;
        unordered_set<int> visit;
        visit.emplace(n);
        queue<int> qu;
        qu.emplace(n);
        int step = 0;
        while (!qu.empty()) {
            int sz = qu.size();
            for (int i = 0; i < sz; i++) {
                int curr = qu.front();
                qu.pop();
                if (curr == 0) return step;
                for (int j = 0; j <= len; j++) {
                    /* add one time */
                    int add = curr + (1 << j);
                    if (add <= upper && !visit.count(add)) {
                        visit.emplace(add);
                        qu.emplace(add);
                    }
                    /* sub one time */
                    int sub = curr - (1 << j);
                    if (sub >= lower && !visit.count(sub)) {
                        visit.emplace(sub);
                        qu.emplace(sub);
                    }
                }
            }
            step++;
        }
        return step;
    }
};
```

```C++
class Solution {
public:
    int minOperations(int n) {
        unordered_map<int, int> memo;
        function<int(int)> dfs = [&](int x)->int {
            if (memo.count(x)) {
                return memo[x];
            }
            if (__builtin_popcount(x) == 1) {
                return 1;
            }
            int y = x - (x & (x - 1));
            int ret = min(dfs(x + y), dfs(x - y)) + 1;
            memo[x] = ret;
            return ret;
        };
        return dfs(n);
    }
};
```
