                if (lcp[i][j] > 0 && (i + 1 < n && j + 1 < n && lcp[i][j] != lcp[i + 1][j + 1] + 1)) {
                    return "";
                } 
            }
        }
        string s(n, ' ');
        char c = 'a';
        for (int i = 0; i < n; i++) {
            if (s[i] == ' ') {
                if (c > 'z') {
                    return "";
                }
                s[i] = c;
                for (int j = i + 1; j < n; j++) {
                    if (lcp[i][j] > 0) {
                        s[j] = s[i];
                    }
                }
                c++;
            }
        }
        return s;
    }
};
```

