    直接模拟
#### 思路
1. 简单题目，贪心法如下:
+ 最大数即将从左向右第一位不为 $9$ 的数字全部变为 $9$ 即可；
+ 最小数即将从左向右第一位不为 $0$ 的数字全部变为 $0$ 即可；
+ 将二者结果相减即可；
2. 复杂度分析：
+ 时间复杂度：$O(n + \log u)$，其中 $n$ 为数组的长度，$u$ 为数组中最大的元素。
+ 空间复杂度：$O(1)$。
#### 代码

```C++
class Solution {
public:
    int minMaxDifference(int num) {
        string s = to_string(num);
        char c1 = -1, c2 = -1;
        for (int i = 0; i < s.size(); i++) {
            if (s[i] != '9' && c1 == -1) {
                c1 = s[i];
            }
            if (s[i] != '0' && c2 == -1) {
                c2 = s[i];
            }
        }
        string s1 = s;
        string s2 = s;
        for (int i = 0; i < s.size(); i++) {
            if (s2[i] == c2) {
                s2[i] = '0';
            }
        }
        if (c1 != -1) {
            for (int i = 0; i < s.size(); i++) {
                if (s1[i] == c1) {
                    s1[i] = '9';
                }
            }
        }
        int num1 = stoi(s1);
        int num2 = stoi(s2);
        return num1 - num2;
    }
};
```

