class Solution {
public:
    vector<int> divisibilityArray(string word, int m) {
        int n = word.size();
        long long curr = 0;
        vector<int> ans;
        for (int i = 0; i < n; i++) {
            curr = (curr * 10 + word[i] - '0') % m;
            if (curr == 0) {
                ans.emplace_back(1);
            } else {
                ans.emplace_back(0);
            }
        }
        return ans;
    }
};
```

