class Solution {
public:
    int minimumScore(string s, string t) {
        int m = s.size(), n = t.size();
        map<int, int> cnt;
        int ans = n;
        for (int i = m - 1, j = n - 1; i >= 0 ; i--) {
            if (s[i] == t[j]) {
                cnt[i] = j--;            
            }
            if (j < 0) {
                return 0;
            }
            ans = min(ans, j + 1);
        }
        for (int i = 0, j = 0; i < m; i++) {
            if (s[i] == t[j]) {
                j++;
                auto it = cnt.upper_bound(i);
                if (it != cnt.end() && it->second >= j) {
                    ans = min(ans, it->second - j);
                } else {
                    ans = min(ans, n - j);
                }
            }
        }
        return ans;
    }
};
```

