class Solution {
public:
    int countAsterisks(string s) {
        vector<int> arr;
        for (int i = 0; i < s.size(); i++) {
            if (s[i] == '|'){
                arr.emplace_back(i);
            }
        }
        for (int i = 0; i < arr.size(); i += 2) {
