        for (int i = 0; i < n; i++) {
            if (degree[i] == 1 && coins[i] == 1) {
                qu.emplace(i);
                degree[i]--;
                visit[i] = true;
            }
        }
        for (int i = 0; i < 2; i++) {
            int sz = qu.size();
            for (int j = 0; j < sz; j++) {
                int curr = qu.front();
                visit[curr] = true;
                qu.pop();
                for (auto v : adj[curr]) {
                    degree[v]--;
                    if (degree[v] == 1) {
                        qu.emplace(v);
                    }
                }
            }
        }
        int tot = 0;
        /* 统计未访问过的节点即可*/
        for (int i = 0; i < n; i++) {
            if (!visit[i]) {
                tot++;
            }
        }
        return tot == 0 ? 0 : (tot - 1) * 2;
    }
};
```

