#### 题意

    直接检测

#### 思路

1. 直接检测矩阵中对角线上的每个元素即可。
2. 复杂度分析：

+ 时间复杂度：$O(n)$。
+ 空间复杂度：$O(1)$。

#### 代码

```C++
class Solution {
public:
    bool isprimer(int x) {
        if (x == 1) {
            return false;
        }
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) {
                return false;
            }
        }
        return true;
    }

    int diagonalPrime(vector<vector<int>>& nums) {
        int n = nums.size();
        int res = 0;
        for (int i = 0; i < n; i++) {
            if (isprimer(nums[i][i])) {
                res = max(res, nums[i][i]);
            }
            if (isprimer(nums[i][n - 1 - i])) {
                res = max(res, nums[i][n - 1 - i]);
            }
        }
        return res;
    }
};
```

