#### 代码

```C++
class Solution {
public:
    vector<long long> findPrefixScore(vector<int>& nums) {
        int n = nums.size();
        vector<long long> res(n);
        vector<int> arr(n);
        int curr = 0;
        for (int i = 0; i < n; i++) {
            curr = max(curr, nums[i]);
            arr[i] = nums[i] + curr;
        }
        res[0] = arr[0];
        for (int i = 1; i < n; i++) {
            res[i] = arr[i] + res[i - 1];
        }
        return res;
    }
};
```

