2. 复杂度分析：

+ 时间复杂度：$O(m\times n \log U)$。
+ 空间复杂度：$O(\log u)$。

#### 代码

```C++
class Solution {
public:
    vector<int> findColumnWidth(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        vector<int> res(n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                res[i] = max(res[i], (int)to_string(grid[j][i]).size());
            }
        }
        return res;
    }
};
```

