>  DFS BFS

#### 思路

1. 不晓得这个题目为啥标记为 $hard$, 本来是非常简单的题目，数据量又给的非常少，不晓得到底是怎么出题的。
2. 直接遍历值大于 $0$ 的位置，并向四周扩展，即求矩阵中每个连通区域的和最大值即可，简单的 $DFS$ 或者 $BFS$ 均可。
4. 复杂度分析：
+ 时间复杂度：$O(mn)$，其中 $m$ 为矩阵的行数，$n$ 为矩阵的列数。
+ 空间复杂度：$O(1)$。

#### 代码

```C++
class Solution {
public:
    int findMaxFish(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        int dir[4][2] = {{0, -1}, {0, 1}, {1, 0}, {-1, 0}};
        int res = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    int curr = 0;
                    queue<pair<int, int>> qu;
                    qu.emplace(i, j);
                    curr += grid[i][j];
                    grid[i][j] = 0;
                    while (!qu.empty()) {
                        auto [x, y] = qu.front();
                        qu.pop();
                        for (int k = 0; k < 4; k++) {
                            int nx = x + dir[k][0];
                            int ny = y + dir[k][1];
                            if (nx >= 0 && ny >= 0 && nx < m && ny < n && grid[nx][ny] > 0) {
                                curr += grid[nx][ny];
                                grid[nx][ny] = 0;
                                qu.emplace(nx, ny);
                            }
                        }
                    }
                    res = max(res, curr);
                }
            }
        }
        return res;
    }
};
```

