class FrequencyTracker {
public:
    FrequencyTracker() {

    }

    void add(int number) {
        if (cnt.count(number)) {
            int x = cnt[number];
            freq[x]--;
            if (freq[x] == 0) {
                freq.erase(x);
            }
            cnt[number]++;
            freq[x + 1]++;
        } else {
            cnt[number] = 1;
            freq[1]++;
        }
    }

    void deleteOne(int number) {
        if (cnt.count(number)) {
            int x = cnt[number];
            freq[x]--;
            if (freq[x] == 0) {
                freq.erase(x);
            }
            cnt[number]--;
            if (cnt[number] == 0) {
                cnt.erase(number);
            }
            if (x - 1 > 0) {
                freq[x - 1]++;
            }
        }
    }

    bool hasFrequency(int frequency) {
        return freq.count(frequency);
    }
private:
    unordered_map<int, int> cnt;
    unordered_map<int, int> freq;
};

```

