class Solution {
public:
    int dfs(int parent, int root, vector<int> &nums, vector<vector<int>> &adj) {
        int res = nums[root];
        for (auto &neg : adj[root]) {
            if (neg == parent) continue;
            res ^= dfs(root, neg, nums, adj);
        }
        return res;
    }

    int minimumScore(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        int m = edges.size();
        int tot = 0;
        int res = INT_MAX;
        vector<vector<int>> dp(n, vector<int>(n));
        vector<vector<int>> adj(n);
        for (int i = 0; i < n; i++) {
            tot ^= nums[i];
        }
        for (auto &e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        for (auto &e : edges) {
            dp[e[0]][e[1]] = dfs(e[0], e[1], nums, adj);
            dp[e[1]][e[0]] = tot ^ dp[e[0]][e[1]];
        }
        for (int i = 0; i < n; i++) {
            vector<bool> visit(n, false);
            visit[i] = true;
            for (auto &neg: adj[i]) {
                queue<int> qu;
                qu.emplace(neg);
                visit[neg] = true;
                while(!qu.empty()) {
                    int curr = qu.front();
                    qu.pop();
                    for (auto & next: adj[curr]) {
                        if (visit[next]) continue;                        
                        res = min(res, max({dp[neg][i], dp[curr][next], tot^dp[neg][i]^dp[curr][next]}) -
                                       min({dp[neg][i], dp[curr][next], tot^dp[neg][i]^dp[curr][next]}));                       
                        visit[next] = true;
                        qu.emplace(next);
                    }
                }
            }
        }        
        return res;
    }
};
```

