class Solution {
public:
    bool dfs(string s, int pos, int cut, int tot, int val) {
        if (pos == s.size()) {
            if (tot == val && cut > 1) {
                return true;
            } else {
                return false;
            }
        } 
        int curr = 0;
        for (int i = pos; i < s.size(); i++) {
            curr = curr * 10 + s[i] - '0';
            if (curr + tot > val) break;
            if (dfs(s, i + 1, cut + 1, tot + curr, val)) {
                return true;
            }
        }
        return false;
    }

    int punishmentNumber(int n) {
        int res = 1;
        for (int i = 2; i <= n; i++) {
            string s = to_string(i * i);
            if (dfs(s, 0, 0, 0, i)) {
                res += i * i;
            }
        }
        return res;
    }
};

```

