        G = [[] for i in range(n)]
        for i, j, w in edges:
            G[i].append([j, w])
            G[j].append([i, w])
        inf = 2 * 10 ** 9
        seen = {}
        found = False
        h = [[0, 0, source, []]]
        while h:
            k, d, i, e = heappop(h)
            if d > target:
                continue
            if k > target:
                return []
            if i == destination:
                # print(d, target, k)
                if k == 0 and d == target or k > 0 and d + k <= target:
