            for (int j = i + 1; j < n; j++) {
                string s1 = to_string(nums[i]);
                string s2 = to_string(nums[j]);
                int x = s1.front() - '0';
                int y = s2.back() - '0';
                if (__gcd(x, y) == 1) {
                    res++;
                }
            }
        }
        return res;
    }
};

