#### 地址

https://leetcode.cn/contest/weekly-contest-352/problems/longest-even-odd-subarray-with-threshold/

#### 题意

    直接模拟

#### 思路

1. 可以直接进行模拟即可，时间复杂度为 $O(n^2)$，还可以继续优化到 $O(n)$ 即可。
2. 复杂度分析：

+ 时间复杂度：$O(n)$，其中 $n$ 表示数组的长度。
+ 空间复杂度：$O(1)$。

#### 代码

```
class Solution {
public:
    int longestAlternatingSubarray(vector<int>& nums, int threshold) {
        int n = nums.size();
        int res = 0;

        auto check = [&](int l, int r) {
            if (nums[l] % 2 != 0) {
                return false;
            }  
            for (int i = l; i < r; i++) {
                if ((nums[i] % 2) == (nums[i + 1] % 2)) {
                    return false;
                }
            }
            for (int i = l; i <= r; i++) {
                if (nums[i] > threshold) {
                    return false;
                }
            }
            return true;
        };
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (check(i, j)) {
                    res = max(res, j - i + 1);          
                }
            }
        }
        return res;
    }
};
```



```C++
class Solution {
public:
    int longestAlternatingSubarray(vector<int>& nums, int threshold) {
        int n = nums.size();
        int i = 0;
        int res = 0;
        while (i < n) {
            while (i < n && ((nums[i] & 1) || nums[i] > threshold)) {
                i++;
            }
            if (i >= n) {
                break;
            }
            int start = i;
            i++;
            while (i < n && nums[i] <= threshold && (nums[i] % 2) != (nums[i - 1] % 2)) {
                i++;
            }
            res = max(res, i - start);
        }
        return res;
    }
};

```



