class Solution {
public:
    string sortVowels(string s) {
        int n = s.size();
        vector<char> t = {'a', 'e', 'i', 'o', 'u'};
        unordered_set<char> cnt(t.begin(), t.end());
        vector<char> arr;
        vector<int> brr;
        for (int i = 0; i < n; i++) {
            if (cnt.count(tolower(s[i]))) {
                arr.emplace_back(s[i]);
                brr.emplace_back(i);
            }
        }
        sort(arr.begin(), arr.end());
        sort(brr.begin(), brr.end());
        for (int i = 0; i < brr.size(); i++) {
            s[brr[i]] = arr[i];
        }
        return s;
    }
};  
```

