struct Trie{
    bool isWord;
    int len;
    vector<Trie *> next;
    Trie() {
        this->isWord = false;
        this->len = 0;
        this->next = vector<Trie *>(26, nullptr);
    }
};

bool insertTrie(struct Trie *trie, string &word) {
    struct Trie *node = trie;
    for (auto c : word) {
        if (node->next[c - 'a'] == nullptr) {
            node->next[c - 'a'] = new Trie();
        }
        node = node->next[c - 'a'];
    }
    node->isWord = true;
