        node = node->next[c - 'a'];
        if (node->isWord) {
            return node->len;
        }
    }
    return -1;
}


class Solution {
public:
    int longestValidSubstring(string word, vector<string>& forbidden) {
        struct Trie *trie = new Trie();
        int maxlen = 0;
        for (auto w : forbidden) {
