```C++
class Solution {
public:
    long long maxArrayValue(vector<int>& nums) {
        int n = nums.size();
        stack<long long> st;
        for (int i = n - 1; i >= 0; i--) {
            if (st.empty()) {
                st.emplace(nums[i]);
            } else if (nums[i] <= st.top()) {
                st.top() += nums[i];
            } else {
                st.emplace(nums[i]);
            }
        }
        return st.top();
    }
}; 
```

