#### 代码

```C++
class Solution {
public:
    int maxIncreasingGroups(vector<int>& usageLimits) {
        sort(usageLimits.begin(), usageLimits.end());
        long long remain = 0, require = 1;
        for (int num : usageLimits) {
            remain += num;
            if (remain >= require) {
                remain -= require;
                require++;
            }
        }
        return require - 1;
    }
};

int maxIncreasingGroups(vector<int>& A) {
    sort(A.begin(), A.end());
    long long total = 0, k = 0;
    for (int a : A) {
        total += a;
        if (total >= (k + 1) * (k + 2) / 2)
            k++;
    }
    return k;
}
```

