+ 空间复杂度：$O(1)$。

#### 代码

```C++
class Solution {
public:
    bool canMakeSubsequence(string str1, string str2) {
        int m = str1.size(), n = str2.size();
        for (int i = 0, j = 0; i < m && j < n; i++) {
            if (str1[i] == str2[j] || ((str2[j] - str1[i] + 26) % 26) == 1) {
                j++;
                if (j == n) {
                    return true;
                }
            }
        }
        return false;
    }
};
