```C++
class Solution {
public:
    int minimumSum(int n, int k) {
        int sum = 0;
        int tot = 0;
        vector<bool> valid(1000, true);
        for (int i = 1; i <= 1000; i++) {
            if (valid[i]) {
                tot++;
                sum += i;
                if (i <= k) {
                    valid[k - i] = false;
                }
            }
            if (tot == n) {
                break;
            }
        }
        return sum;
    }
};
```

