class Solution {
public:
    int furthestDistanceFromOrigin(string moves) {
        int cnt1 = 0, cnt2 = 0;
        for (auto c : moves) {
            if (c == 'L') cnt1--;
            if (c == 'R') cnt1++;
            if (c == '_') cnt2++;
        }
        return abs(cnt1) + cnt2;
    }
};
```

