#### 代码

```C++
class Solution {
public:
    long long minimumPossibleSum(int n, int target) {
        int m = target / 2;
        if (n <= m) {
            return n * (n + 1) / 2;
        } else {
            return (long long)m * (m + 1) / 2 + (long long)(n - m) * (target * 2 + n - m - 1) / 2;   
        }
    }
};
```

