class Solution {
public:
    int countWays(vector<int>& nums) {
        int n = nums.size();
        int res = 0;
        sort(nums.begin(), nums.end());
        if (nums[0] > 0) res++;
        for (int i = 0; i < n; i++) {
            if (i + 1 > nums[i]) {
                if (i + 1 == n) {
                    res++;
                } else {
                    if (nums[i + 1] > i + 1) {
                        res++;
                    }
                }
            }
        }
        return res;
    }
};
```

