class Solution {
public:
    int minOperations(vector<int>& nums, int k) {
        int n = nums.size();
        unordered_set<int> cnt;
        int res = 0;
        for (int i = nums.size() - 1; i >= 0; i--) {
            if (nums[i] <= k) {
                cnt.emplace(nums[i]);
            }
            if (cnt.size() == k) {
                return n - i;
            }
        }
        return -1;
    }
};
