        function<int(int, int)> dfs = [&](int root, int parent)-> int {
            long long sum = values[root];
            for (auto v : graph[root]) {
                if (v == parent) continue;
                int curr = dfs(v, root);
                sum += curr;
            }
            if (sum % k == 0) {
                res++;
            } 
            return sum % k;
        };
        dfs(0, -1);
        return res;
    }
};
```


