```C++
class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        degree = [0] * n
        for x, y in edges:
            degree[y] += 1
        arr = [i for i, x in enumerate(degree) if x == 0]
        if len(arr) == 1:
            return arr[0]
        return -1
```

