        let m = grid.len();
        let n = grid[0].len();
        let mut psum = vec![vec![0; n + 1]; m + 1];
        let mut res = 0;
        for i in 1..= m {
            for j in 1..= n {
                psum[i][j] = psum[i - 1][j] + psum[i][j - 1] - psum[i - 1][j - 1] + grid[i - 1][j - 1];
                if psum[i][j] <= k {
                    res += 1;
                }
            }
        }
        res
    }
