impl Solution {
    pub fn sum_of_power(nums: Vec<i32>, k: i32) -> i32 {
        let n = nums.len();
        let MOD: i64 = 1_000_000_007;
        let mut f: Vec<Vec<i64>> = vec![vec![0; (k + 1) as usize]; (n + 1)];

        f[0][0] = 1;
        for x in nums {
            if x > k {
                continue;
            }
            for i in (1..= n).rev() {
                for j in (x..= k).rev() {
                    f[i][j as usize] = (f[i][j as usize] + f[i - 1][(j - x) as usize]) % MOD;
                }
            }
        }

        let mut res = 0;
        let mut cur = 1;
        for i in (1..=n).rev() {
            res = (res + cur * f[i][k as usize]) % MOD;
            cur = (cur * 2) % MOD;
        }
        res as i32
    }
}
```



