class Solution:
    def sumOfPower(self, nums: List[int], k: int) -> int:
        n = len(nums)
        mod = 10**9 + 7
        f = [[0] * (k + 1) for _ in range(n + 1)]
        f[0][0] = 1
        for x in nums:
            if (x > k):
                continue
            for i in range(n, 0, -1):
                for j in range(k, x - 1, -1):
                    f[i][j] = (f[i][j] + f[i - 1][j - x]) % mod

        res, cur = 0, 1
        for i in range(n, 0, -1):
            res = (res + cur * f[i][k]) % mod
            cur = cur * 2 % mod
        return res
