impl Solution {
    pub fn max_bottles_drunk(num_bottles: i32, num_exchange: i32) -> i32 {
        let mut num_exchange = num_exchange;
        let mut res = num_bottles;
        let mut tot = num_bottles;
        while tot >= num_exchange {
            res += 1;
            tot -= num_exchange - 1;
            num_exchange += 1;
        }
