```Rust
impl Solution {
    pub fn sum_of_the_digits_of_harshad_number(x: i32) -> i32 {
        let mut sum = 0;
        let mut a = x;
        while a > 0 {
            sum += a % 10;
            a /= 10;
        }
        if x % sum == 0 {sum} else {-1}
    }
}
