```Rust
impl Solution {
    pub fn score_of_string(s: String) -> i32 {
        s.chars()
        .skip(1)
        .enumerate()
        .map(|(i, c)| (c as i32 - s.chars().nth(i).unwrap() as i32).abs())
        .sum()
    }
}
