class Solution:
    def minRectanglesToCoverPoints(self, points: List[List[int]], w: int) -> int:
        points.sort()
        res = 1
        end = points[0][0] + w
        for x, y in points:
            if x > end:
                end = x + w
                res += 1
        return res
```

```Rust
impl Solution {
    pub fn min_rectangles_to_cover_points(points: Vec<Vec<i32>>, w: i32) -> i32 {
        let mut points = points;
        points.sort();
        let mut res = 1;
        let mut end = points[0][0] + w;
        for point in points {
            let x = point[0];
            if x > end {
                end = x + w;
                res += 1;
            }
        }
        res
    }
}
