#### 地址

https://leetcode.cn/contest/weekly-contest-391/problems/count-alternating-subarrays/

#### 题意

>  dijistra

#### 思路

1. 典型的 `dijistra` 求最短距离的模版题目，感觉没有什么好说的，照着写即可；

2. 复杂度：

+ 时间复杂度：$O(n \log n)$，其中 $n$ 表示给定数组的长度；
+ 空间复杂度：$O(1)$；

#### 代码

```C++
class Solution {
public:
    vector<int> minimumTime(int n, vector<vector<int>>& edges, vector<int>& disappear) {
        vector<int> dist(n, INT_MAX);
        vector<unordered_map<int, int>> graph(n);
        vector<bool> vis(n, false);

        for (auto e : edges) {
            int x = e[0], y = e[1], cost = e[2];
            if (graph[x].count(y)) {
                graph[x][y] = min(graph[x][y], cost);
                graph[y][x] = min(graph[x][y], cost);
            } else {
                graph[x][y] = cost;
                graph[y][x] = cost;
            }
        }

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        pq.emplace(0, 0);
        dist[0] = 0;

        while (!pq.empty()) {
            auto [cost, cx] = pq.top();
            pq.pop();
            if (vis[cx]) continue;
            vis[cx] = true;

            for (auto [nx, ncost]: graph[cx]) {
                if (cost + ncost >= disappear[nx]) continue;
                if (cost + ncost >= dist[nx]) continue;
                pq.emplace(cost + ncost, nx);
                dist[nx] = cost + ncost;
            }
        }

        for (int i = 0; i < n; i++) {
            if (dist[i] == INT_MAX) {
                dist[i] = -1;
            }
        }

        return dist;
    }
};
```



```Python
from collections import defaultdict
import heapq

class Solution:
    def minimumTime(self, n: int, edges: List[List[int]], disappear: List[int]) -> List[int]:
        dist = [float('inf')] * n
        graph = defaultdict(dict)
        vis = [False] * n

        for x, y, cost in edges:
            if y in graph[x]:
                graph[x][y] = min(graph[x][y], cost)
                graph[y][x] = min(graph[x][y], cost)
            else:
                graph[x][y] = cost
                graph[y][x] = cost

        pq = [(0, 0)]
        dist[0] = 0

        while pq:
            cost, cx = heapq.heappop(pq)
            if vis[cx]:
                continue
            vis[cx] = True

            for nx, ncost in graph[cx].items():
                if cost + ncost >= disappear[nx]:
                    continue
                if cost + ncost >= dist[nx]:
                    continue
                heapq.heappush(pq, (cost + ncost, nx))
                dist[nx] = cost + ncost

        for i in range(n):
            if dist[i] == float('inf'):
                dist[i] = -1

        return dist
```

