#### 代码

```python
class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        n = len(coins)
        res = 0
        lo, hi = 1, 10**20
        while lo <= hi:
            mid = (lo + hi) // 2
            tot = 0
            for i in range(1, 1 << n):
                lcm = 1
                cnt = 0
                for j in range(len(coins)):
                    if i & (1 << j):
                        cnt += 1
                        lcm = coins[j] * lcm // math.gcd(lcm, coins[j])
                cur = mid // lcm
                tot += cur if cnt % 2 == 1 else -cur

            if tot >= k:
                res = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return res
