            let x = edges[i][0];
            let y = edges[i][1];
            let cost = edges[i][2];
            graph[x as usize].push((y, cost));
            graph[y as usize].push((x, cost));
        }

        fn dijkstra(start: i32, n: usize, graph: &Vec<Vec<(i32, i32)>>) -> Vec<i64> {
