#### 代码
```C++
class Solution {
public:
    char repeatedCharacter(string s) {
        vector<int> cnt(26);
        for (int i = 0; i < s.size(); i++) {
            cnt[s[i] - 'a']++;
            if (cnt[s[i] - 'a']> 1) {
                return s[i];
            }
        }
        return 'a';
    }
};
```

