class Solution:
    def queryResults(self, limit: int, queries: List[List[int]]) -> List[int]:
        res = []
        color = {}
        cnt = defaultdict(int)
        for x, y in queries:
            if x in color:
                cnt[color[x]] -= 1
                if cnt[color[x]] == 0:
                    del cnt[color[x]]
            cnt[y] += 1
            color[x] = y
            res.append(len(cnt))
