                dp2[i + 1][j + 1] = dp2[i][j + 1] + dp2[i + 1][j] - dp2[i][j]
                if grid[i][j] == 'X':
                    dp1[i + 1][j + 1] += 1
                if grid[i][j] == 'Y':
                    dp2[i + 1][j + 1] += 1
                if dp1[i + 1][j + 1] > 0 and dp1[i + 1][j + 1] == dp2[i + 1][j + 1]:
