            for val in range(k):
                if cnt[val] == 0:
                    continue
                diff = abs(val - target)
                cost = min(diff, k - diff)
                total += cost * cnt[val]
            return total

        cost_even = [compute_cost(cnt_even, i) for i in range(k)]
        cost_odd = [compute_cost(cnt_odd, i) for i in range(k)]

        res = float('inf')
        for i in range(k):
            for j in range(k):
                if i == j:
                    continue
                res = min(res, cost_even[i] + cost_odd[j])

        return res
```

