        for (int i = 0; i < m - 1; i++) {
            int x = removeQueries[i];
            auto it = cnt.lower_bound({x,0});
            int r = it->first.first;
            int l = it->first.second;
            long long s = it->second;
            cnt.erase(it);
            now[s]--;
            if(now[s] == 0) {
                now.erase(s);
            }
            if (x > l) {
                cnt[make_pair(x - 1, l)] = sum[x] - sum[l];
                now[sum[x] - sum[l]]++;
            }
            if (x < r) {
                cnt[make_pair(r, x + 1)] = sum[r+1] - sum[x+1];
                now[sum[r+1] - sum[x+1]]++;
            }
            ans[i] = now.rbegin()->first;
        }
        return ans;
    }
};
```
+ 并查集
```C++
class Solution {
public:
    int find(vector<int> &f, int x) {
        while (x != f[x]) {
            x = f[x];
        }
        return x;
    }

    void uni(vector<int> &f, vector<long long> &sum, int x, int y) {
        int fx = find(f, x);
        int fy = find(f, y);
        f[fx] = fy;
        sum[fy] += sum[fx];
    }

    vector<long long> maximumSegmentSum(vector<int>& nums, vector<int>& removeQueries) {
        int n = nums.size();
        long long curr = 0;
        vector<int> fa(n, -1);
        vector<long long> sum(n, 0);
        vector<long long> ans(n, 0);
        for (int i = n - 1; i >= 0; i--) {
            ans[i] = curr;
            int x = removeQueries[i];
            fa[x] = x;
            sum[x] = nums[x];
            if (x - 1 >= 0 && fa[x - 1] >= 0) {
                uni(fa, sum, x, x - 1);
            }
            if (x + 1 < n && fa[x + 1] >= 0) {
                uni(fa, sum, x, x + 1);
            }
            curr = max(curr, sum[find(fa, x)]);
        }
        return ans;
    }
};
```

