#### 思路
1. 感觉这个题目只能算是简单题目，感觉没什么好说的，标准的模板题目。
2. 复杂度分析：
+ 时间复杂度：$O(m \times n)$, 其中 $m, n$ 为矩阵的行数与列数。
+ 空间复杂度：$O(m \times n)$, 其中 $m, n$ 为矩阵的行数与列数。

#### 代码
+ dijkstra
```C++
class Solution {
public:
    int minimumObstacles(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        int res = INT_MAX;
        vector<vector<int>> cost(m, vector<int>(n, m * n));
        int dir[4][2] = {{0, -1}, {0, 1}, {1, 0}, {-1, 0}};

        /* dijistra */
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
        pq.emplace(0, 0);
        cost[0][0] = 0;
        while(!pq.empty()) {
            auto [c, p] = pq.top();
            pq.pop();
            int x = p / n;
            int y = p % n;
            if(x == m - 1 && y == n - 1) {
                break;
            }
            for (int i = 0; i < 4; i++) {
                int nx = x + dir[i][0];
                int ny = y + dir[i][1];
                if (nx >= 0 && ny >= 0 && nx < m && ny < n) {
                    if (grid[x][y] + c < cost[nx][ny]) {
                        pq.emplace(grid[x][y] + c, nx * n + ny);
                        cost[nx][ny] = grid[x][y] + c;
                    }
                }
            }
        }
        return cost[m - 1][n - 1];
    }
};
```
+ BFS
```C++
class Solution {
public:
    int minimumObstacles(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        vector<vector<int>> cost(m, vector<int>(n, INT_MAX));
        queue<pair<int,int>> qu;
        qu.emplace(0, 0);
        cost[0][0] = 0;
        int dir[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while(!qu.empty()) {
            auto [x, y] = qu.front();
            qu.pop();
            for (int i = 0; i < 4; i++) {
                int nx = x + dir[i][0];
                int ny = y + dir[i][1];
                if (nx >= 0 && ny >= 0 && nx < m && ny < n) {
                    if (cost[x][y] + grid[nx][ny] < cost[nx][ny]) {
                        qu.emplace(nx, ny);
                        cost[nx][ny] = cost[x][y] + grid[nx][ny];
                    }
                }
            }
        }
        return cost[m - 1][n - 1];
    }
};
```

