2. 复杂度分析：
+ 时间复杂度：$O(n)$，其中 $n$ 表示数组的长度。
+ 空间复杂度：$O(n)$，其中 $n$ 表示数组的长度。
#### 代码
```C++
class Solution {
public:
    int mostFrequentEven(vector<int>& nums) {
        map<int,int> cnt;
        for (auto v : nums) {
            if (v % 2 == 0) {
                cnt[v]++;
            }
        }
        int ans = -1, freq = 0;
        for (auto [x, f] : cnt) {
            if (f > freq) {
                ans = x;
                freq = f;
            }
        }
        return ans;
    }
};
```

