#### 代码
```C++
class Solution {
public:
    int partitionString(string s) {
        vector<int> cnt(26);
        int ans = 1;
        for (int i = 0; i < s.size(); i++) {
            if (cnt[s[i] - 'a'] == 0) {
                cnt[s[i] - 'a']++;
            } else {
                cnt = vector<int>(26);
                ans++;
                cnt[s[i] - 'a']++;
            }
        }
        return ans;
    }
};
```

