#### 地址
https://leetcode.cn/problems/sum-of-prefix-scores-of-strings/
#### 题意
> trie树
#### 思路
1. 感觉这个是个中等难度的题目，首先利用 `trie` 树存储所有字符串的前缀的统计次数。对于字符串 $s$ 进行搜索时，我们将在 `trie` 树中遇到的所有的前缀的统计次数叠加即可，不需要特别复杂的思考的问题。
2. 复杂度分析：
+ 时间复杂度：$O(n \times m)$，其中 $n$ 表示的数组的长度，$m$ 表示每个字符串的平均长度。
+ 空间复杂度：$O(n \times m)$，其中 $n$ 表示的数组的长度，$m$ 表示每个字符串的平均长度。

#### 代码

```C++
struct Trie{
    bool isWord;
    int cnt;
    vector<Trie *> next;
    Trie(){
        this->isWord = false;
        this->next = vector<Trie *>(26, nullptr);
        this->cnt = 0;
    }
};

void insert(Trie * root, string word) {
    Trie *node = root;
    for (auto c : word) {
        if (!node->next[c - 'a']) {
            node->next[c - 'a'] = new Trie();
        }
        node = node->next[c - 'a'];
        node->cnt++;
    }
}

int search(Trie *root, string word) {
    int ans = 0;
    Trie *node = root;
    for (auto c : word) {
        if (!node->next[c - 'a']) {
            return ans;
        }
        node = node->next[c - 'a'];
        ans += node->cnt;
    }
    return ans;
}

class Solution {
public:
    vector<int> sumPrefixScores(vector<string>& words) {
        Trie *root = new Trie();
        for (auto word : words) {
            insert(root, word);
        }
        vector<int> ans;
        for (int i = 0; i < words.size(); i++) {
            ans.emplace_back(search(root, words[i]));
        }
        return ans;
    }
};
```

