```
示例 3：
```
输入 ：
num = 3
plate = [".....","....O","....O","....."]

输出：[]

解释：
由于弹珠被击中后只能前进 3 步，且不能在弹珠洞和弹珠盘四角打入弹珠，故不存在能让弹珠入洞的打入位置。
```
提示：
+ `1 <= num <= 10^6`
+ `1 <= plate.length, plate[i].length <= 1000`
+ `plate[i][j]` 仅包含 `"O"、"W"、"E"、"."`

#### 地址
https://leetcode.cn/contest/season/2022-fall/problems/EXvqDp/
#### 题意
    BFS
#### 思路
1. 感觉这个题目暴力模拟即可，由于只有两个方向改变，所以可能每个弹珠的轨迹不会成环。所以我们只需要进行暴力模拟即可。
2. 复杂度分析
+ 时间复杂度：时间复杂度为 $O(n^2)$，$n$ 为矩阵的行数。
+ 空间复杂度：时间复杂度为 $O(n^2)$，$n$ 为矩阵的行数。
#### 代码
```C++
class Solution {
public:
    bool check(int step, int x, int y, int d, vector<string>& plate) {
        int m = plate.size();
        int n = plate[0].size();
        int dirs[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        while (step >= 0) {
            if (plate[x][y] == 'O') {
                return true;
            } else if (plate[x][y] == '.') {
                int nx = dirs[d][0] + x;
                int ny = dirs[d][1] + y;
                if (nx >= 0 && ny >= 0 && nx < m && ny < n) {
                    x = nx;
                    y = ny;

                    step--;
                } else {
                    break;
                }
            } else if (plate[x][y] == 'E') {
                int nx = dirs[(d + 1 + 4) % 4][0] + x;
                int ny = dirs[(d + 1 + 4) % 4][1] + y;
                if (nx >= 0 && ny >= 0 && nx < m && ny < n) {
                    x = nx;
                    y = ny;
                    d = (d + 1 + 4) % 4;

                    step--;
                } else {
                    break;
                }
            } else if (plate[x][y] == 'W') {
                int nx = dirs[(d - 1 + 4) % 4][0] + x;
                int ny = dirs[(d - 1 + 4) % 4][1] + y;
                if (nx >= 0 && ny >= 0 && nx < m && ny < n) {
                    x = nx;
                    y = ny;
                    d = (d - 1 + 4) % 4;

                    step--;
                } else {
                    break;
                }
            }
            if (step < 0) {
                break;
            }
        }
        return false;
    }

    vector<vector<int>> ballGame(int num, vector<string>& plate) {
        int m = plate.size();
        int n = plate[0].size();
        vector<vector<int>> ans;
        for (int i = 1; i < m - 1; i++) {
            if (plate[i][0] == '.') {
                if (check(num, i, 0, 0, plate)) {
                    ans.push_back({i, 0});
                }
            }
        }
        for (int i = 1; i < n - 1; i++) {
            if (plate[0][i] == '.') {
                if (check(num, 0, i, 1, plate)) {
                    ans.push_back({0, i});
                }
            }
        }
        for (int i = 1; i < m - 1; i++) {
            if (plate[i][n - 1] == '.') { 
                if (check(num, i, n - 1, 2, plate)) {
                    ans.push_back({i, n - 1});
                }
            }
        }
        for (int i = 1; i < n - 1; i++) {
            if (plate[m - 1][i] == '.') {
                if (check(num, m - 1, i, 3, plate)) {
                    ans.push_back({m - 1, i});
                }
            }
        }
        return ans;
    }
};
```

### 4. 二叉树灯饰

#### 题目

「力扣嘉年华」的中心广场放置了一个巨型的二叉树形状的装饰树。每个节点上均有一盏灯和三个开关。节点值为 `0` 表示灯处于「关闭」状态，节点值为 `1` 表示灯处于「开启」状态。每个节点上的三个开关各自功能如下：
+ 开关 `1`：切换当前节点的灯的状态；
+ 开关 `2`：切换 以当前节点为根 的子树中，所有节点上的灯的状态，；
+ 开关 `3`：切换 当前节点及其左右子节点（若存在的话） 上的灯的状态；
给定该装饰的初始状态 `root` ，请返回最少需要操作多少次开关，可以关闭所有节点的灯。

示例 1：
```
输入：root = [1,1,0,null,null,null,1]

输出：2

