class Solution {
public:
    bool equalFrequency(string word) {
        vector<int> cnt(26);
        for (auto c : word) {
            cnt[c - 'a']++;
        }
        for (int i = 0; i < 26; i++) {
            if (cnt[i] > 0) {
                cnt[i]--;
                int prev = 0;
                bool isEqual = true;
                for(int j = 0; j < 26; j++) {
                    if (cnt[j] > 0) {
                        if (prev == 0) {
                            prev = cnt[j];
                        } else if (prev != cnt[j]){
                            isEqual = false;
                            break;
                        }
                    }
                }
                cnt[i]++;
                if (isEqual) {
                    return true;
                }
            }
        }
        return false;
    }
};
```

