        for (int i = 0; i < n; i++) {
            if (nums[i] == minK) minIdx = i;
            if (nums[i] == maxK) maxIdx = i;
            if (nums[i] > maxK || nums[i] < minK) validIdx = i;
            ans += max(0, min(minIdx, maxIdx) - validIdx); 
        }
        return ans;
    }
};
```

