```C++
class Solution {
public:
    int destroyTargets(vector<int>& nums, int space) {
        int n = nums.size();
        unordered_map<int, int> cnt;
        for (int i = 0; i < n; i++) {
            cnt[nums[i] % space]++;
        }
        int ans = 0, freq = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[i] % space;
            if (cnt[x] > freq || (cnt[x] == freq && nums[i] < ans)) {
                ans = nums[i];
                freq = cnt[x];
            }
        }
        return ans;
    }
};
```

### 6227. 下一个更大元素 IV

#### 题目

给你一个下标从 `0` 开始的非负整数数组 `nums` 。对于 `nums` 中每一个整数，你必须找到对应元素的 第二大 整数。

如果 `nums[j]` 满足以下条件，那么我们称它为 `nums[i]` 的 第二大 整数：
+ `j > i`
+ `nums[j] > nums[i]`
恰好存在 一个 `k` 满足 `i < k < j` 且 `nums[k] > nums[i]` 。
如果不存在 `nums[j]` ，那么第二大整数为 `-1` 。

比方说，数组 `[1, 2, 4, 3] `中，`1` 的第二大整数是 `4 `，`2` 的第二大整数是 `3` ，`3` 和 `4 `的第二大整数是 -1 。
请你返回一个整数数组 `answer` ，其中 `answer[i]`是 `nums[i]` 的第二大整数。



示例 1：
```
输入：nums = [2,4,0,9,6]
输出：[9,6,6,-1,-1]
解释：
下标为 0 处：2 的右边，4 是大于 2 的第一个整数，9 是第二个大于 2 的整数。
下标为 1 处：4 的右边，9 是大于 4 的第一个整数，6 是第二个大于 4 的整数。
下标为 2 处：0 的右边，9 是大于 0 的第一个整数，6 是第二个大于 0 的整数。
下标为 3 处：右边不存在大于 9 的整数，所以第二大整数为 -1 。
下标为 4 处：右边不存在大于 6 的整数，所以第二大整数为 -1 。
所以我们返回 [9,6,6,-1,-1] 。
```
示例 2：
```
输入：nums = [3,3]
输出：[-1,-1]
解释：
由于每个数右边都没有更大的数，所以我们返回 [-1,-1] 。
```


提示：
+ `1 <= nums.length <= 105`
+ `0 <= nums[i] <= 109`

#### 地址
https://leetcode.cn/contest/biweekly-contest-90/problems/next-greater-element-iv/
#### 题意
>  数学问题
#### 思路
1. 我们将本题拆分成两个子问题：
+ 下一个更大的元素；
+ 从 $i$ 开始找到第一个比 $x$ 大的数；
如果上面两个子问题都可以解决，那么本题就是一个常规题目了。
2. 首先我们找到每个元素 $nums[i]$ 下一个更大元素的位置为 $j$，然后从 $j + 1$ 处开始查找第一个比 $nums[i]$ 大的元素，此时我们可以利用线段树上二分查找。
3. 排序也非常简单的问题，排序也是非常好的思路来解决该问题，我们将所有的元素按照从大道小的顺序进行排序，同时对于相同的元素按照索引的小到大的顺序来进行排序，此时我们从大到小依次将元素的索引加入到有序集合中，保证每次加入 $nums[i]$ 时，集合中只保存大于 $nums[i]$ 的元素，每次我们查询有序集合中第一个大于 $i$ 的索引为 $j$ 即可，再往后移动一个元素即可。
4. 
5. 复杂度分析：
+ 时间复杂度：$O(n \log n)$，其中 $n$ 表示给定的数组的长度。
+ 空间复杂度：$O(n)$，其中 $n$ 表示给定的数组的长度。

#### 代码
```C++
class Solution {
public:
    vector<int> secondGreaterElement(vector<int>& nums) {
        int n = nums.size();
        vector<int> right(n, -1);
        vector<int> ans(n, -1);
        stack<int> st;
        st.emplace(n - 1);
        for (int i = n - 2; i >= 0; i--) {
            while (!st.empty() && nums[st.top()] <= nums[i]) {
                st.pop();
            }
            if (!st.empty()) {
                right[i] = st.top();
            }
            st.emplace(i);
        }
        this->tmax = vector<int>(n * 4 + 10);
        this->nums = nums;
        buildTree(0, n - 1, 1);
        for (int i = 0; i < n; i++) {
            if (right[i] != -1) {
                int x = queryRight(right[i] + 1, nums[i], 0, n - 1, 1);
                ans[i] = x;
            }
        }        
        return ans;
    }

    void buildTree(int l, int r, int idx) {
        if (l == r) {
            tmax[idx] = nums[l];
        } else {
            int mid = (l + r) >> 1;
            buildTree(l, mid, idx * 2);
            buildTree(mid + 1, r, idx * 2 + 1);
            tmax[idx] = max(tmax[idx * 2], tmax[idx * 2 + 1]);
        }
    }

    int queryRight(int start, int val, int l, int r, int idx) {
        if (r < start) {
            return -1;
        }
        if (tmax[idx] <= val) {
            return -1;
        }
        if (l == r) {
            return nums[l];
        } else {
            int mid = (l + r) >> 1;
            int ret = -1;
            if (tmax[idx * 2] > val) {
                ret = queryRight(start, val, l, mid, idx * 2);
            } 
            if (ret == -1) {
                ret = queryRight(start, val, mid + 1, r, idx * 2 + 1);
            }
            return ret;
        }
    } 
private:
    vector<int> tmax;
    vector<int> nums;
};
```

+ 排序 + 二分查找
```C++
class Solution {
public:
    vector<int> secondGreaterElement(vector<int>& nums) {
        int n = nums.size();
        vector<pair<int, int>> arr;
        for (int i = 0; i < nums.size(); i++) {
            arr.emplace_back(nums[i], i);
        }
        sort(arr.begin(), arr.end(), [](const pair<int, int> &a, const pair<int, int> &b) {
            if (a.first == b.first) {
                return a.second < b.second;
            } 
            return a.first > b.first;
        });
        set<int> cnt;
        vector<int> ans(n, -1);
        for (auto [x, i] : arr) {
            auto it = cnt.lower_bound(i);
            if (it != cnt.end() && (++it) != cnt.end()) {
                ans[i] = nums[*it];
            }
            cnt.emplace(i);
        }
        return ans;
    }
};
```

