2. 我们每次从 $i$ 开始往后遍历, 找到从 $i$ 到 $n$ 的连续子序列的和等于 $x$ 的最短长度. 我们从 $i$ 往前开始往前遍历,依次遍历每一个截至到 $i$ 的连续子序列的和 $curr$ ,同时我们从 $i+1$ 往后找到 $dp[k-curr]$. 
![](https://i.loli.net/2021/10/27/fg5rpOQyvUw3iIc.png)
我们找到递推公式如下:
$$ dp[k] = min(dp[k], x + d[k-i])$$
3. 复杂度分析:
+ 时间复杂度分析: 时间复杂度为 $O(n\times k)$ , 其中 $n$ 为数组的长度, $k$ 为目标要求的和.
+ 空间复杂度分析: 空间复杂度为$O(k)$．
### 代码
```c++
#include<iostream>
#include<vector>
#include<set>
#include<unordered_set>
#include<map>
#include<unordered_map>
#include<string>
#include<stack>
#include<algorithm>
#include<limits.h>
#include<string.h>

using namespace std;

void slove(int t){
    int n,k;
    vector<int> arr;

    cin>>n>>k;
    arr = vector<int>(n);
    for(int i = 0; i < n; ++i){
        cin>>arr[i];
    }

    vector<int> dp(k+1,n+1);
    dp[0] = 0;
    for(int i = n - 1; i >= 0; --i) {
        long long curr = 0;
        for(int j = i; j >= 0; --j) {
            curr += arr[j];
            if(curr <= k) {
                dp[k] = min(dp[k],dp[k-curr]+i+1-j);
            }
        }
        curr = 0;
        for(int j = i; j < n; ++j) {
            curr += arr[j];
            if(curr <= k){
                dp[curr] = min(dp[curr],j+1-i);
            }
        }
    }
    cout<<"Case #"<<t<<": ";
    cout<<(dp[k] > n ? -1 : dp[k])<<endl;
}

int main(){
    int t;
    cin>>t;
    for(int i = 0; i < t; ++i){
        slove(i+1);
    }
    return 0;
}
```

