funcs = [plus, sub, mul, my_div, my_mod, my_inv_div, my_inv_mod,
         bit_and, bit_or, bit_xor, const, only_x, only_y, quad_x, quad_y]


class Expression:
    def __init__(self, s):
        self.s = '(' + s + ')'

    def evaluate(self, func):
        nums = []
        ops = []
        curr = 0
        is_num = False
        for c in self.s:
            if c == '(':
                if is_num:
                    nums.append(curr)
                    is_num = False
                ops.append('(')
            elif c in '+*#':
                if is_num:
                    nums.append(curr)
                    is_num = False
                ops.append(c)
            elif c == ')':
                if is_num:
                    nums.append(curr)
                    is_num = False
                while ops[-1] != '(':
                    op = ops.pop()
                    b = nums.pop()
                    a = nums.pop()
                    if op == '+':
                        nums.append(a + b)
                    elif op == '*':
                        nums.append(a * b)
                    else:
                        nums.append(func(a, b))
                ops.pop()
            else:
                if not is_num:
                    curr = 0
                    is_num = True
                curr = curr * 10 + int(c)
        assert(len(nums) == 1)
        return nums[0]

    def __eq__(self, other):
        for func in funcs:
            a = self.evaluate(func)
            b = other.evaluate(func)
            if a != b:
                return False
        return True


t = read_int()
for case_num in range(1, t + 1):
    n = read_int()
    expressions = [Expression(input()) for _ in range(n)]

    color = [0] * n
    color[0] = 1
    new_color = 2
    for i in range(1, n):
