#include<map>
#include<unordered_map>
#include<string>
#include<stack>
#include<algorithm>

using namespace std;
typedef pair<int,int> pii;

void slove(int t){
    int n,k,s;
    int ans = 0;
    cin>>n>>k>>s;
    ans = k + min(n,k+n-2*s);
    cout<<ans<<endl;
}

int main(){
    int t;
    cin>>t;
    for(int i = 0; i < t; ++i){
        cout<<"Case #"<<i+1<<": ";
        slove(i+1);
    }
    return 0;
}
```

