class Solution {
public:
    ListNode* removeNodes(ListNode* head) {
        vector<int> st;
        while(head) {
            while (st.size() > 0 && head->val > st.back()) {
                st.pop_back();
            }
            st.emplace_back(head->val);
            head = head->next;
        }
        ListNode *res = new ListNode(st[0]);
        ListNode *curr = res;
        for (int i = 1; i < st.size(); i++) {
            curr->next = new ListNode(st[i]);
            curr= curr->next;
        }
        return res;
    }
};
```
