class Solution {
public:
    ListNode* removeNodes(ListNode* head) {
        if (!head) {
            return nullptr;
        }
        ListNode *node = removeNodes(head->next);
        if (node && node->val > head->val) {
            return node;
        } else {
            head->next = node;
            return head;
        }
    }
};
```

