#### 代码
```C++
class Solution {
public:
    int similarPairs(vector<string>& words) {
        int n = words.size();
        vector<vector<bool>> cnt(n, vector<bool>(26));
        for (int i = 0; i < n; i++) {
            for (auto c : words[i]) {
                cnt[i][c - 'a'] = true;
            }
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (cnt[i] == cnt[j]) {
                    ans++;
                }
            }
        }
        return ans;
    }
};
```

