#### 题意
    直接遍历
#### 思路
1. 将每个字符串进行转换，如果只含有数字则进行转换，否则则不进行转换。
2. 复杂度分析：
+ 时间复杂度：$O(mn)$。
+ 空间复杂度：$O(1)$。
#### 代码
```C++
class Solution {
public:
    int maximumValue(vector<string>& strs) {
        int n = strs.size();
        int res = 0;
        for (int i = 0; i < n; i++) {
            bool isNum = true;
            for (auto c : strs[i]) {
                if (!isdigit(c)) {
                    isNum = false;
                    break;
                }
            }
            if (!isNum) {
                res = max(res, int(strs[i].size()));
            } else {
                res = max(res, stoi(strs[i]));
            }
        }
        return res;
    }
};
```

