        long long sum2 = accumulate(nums2.begin(), nums2.end(), 0LL);
        if (sum1 != sum2) {
            return -1;
        }
        int n = nums1.size();
        long long res = 0;
        for (int i = 0; i < n; i++) {
            long long x = nums1[i] - nums2[i];
            if (k == 0) {
                if (x != 0) {
                    return -1;
                } 
                continue;
            }
            if (x % k != 0) {
                return -1;
            }
            if (x > 0) {
                res += x / k;
            }
        }
        return res;
    }
};
```

