```C++
class Solution {
public:
    bool check(vector<int> &arr) {
        if (arr.size() % 2) {
            return false;
        }
        for (int i = 0; i < arr.size(); i += 2) {
            if (arr[i] != arr[i + 1]) {
                return false;
            }
        }
