    }

    long long minCost(vector<int>& basket1, vector<int>& basket2) {
        sort(basket1.begin(), basket1.end());
        sort(basket2.begin(), basket2.end());
        int n = basket1.size();
        vector<int> arr1, arr2;
        vector<int> arr;
