            arr1.emplace_back(basket1[i++]);
        }
         while (j < n) {
            arr2.emplace_back(basket2[j++]);
        }
        if (arr1.size() != arr2.size()) {
            return -1;
        }
        if (!check(arr1) || !check(arr2)) {
            return -1;
        }
        long long ans = 0;
        int minVal = max(basket1[n - 1], basket2[n - 1]);
        if (arr.size() > 0) {
            minVal = min(arr[0], minVal);
        }
        int l1 = 0, l2 = 0;
        int m = arr1.size() / 2;
        for (int i = 0; i < m; i++) {
            if (arr1[l1] < arr2[l2]) {
                if (2 * minVal < arr1[l1]) {
                    ans += 2 * minVal;
                } else {
                    ans += arr1[l1];
                }
                minVal = min(minVal, arr1[l1]);
                l1 += 2;
            } else {
                if (2 * minVal < arr2[l2]) {
                    ans += 2 * minVal;
                } else {
                    ans += arr2[l2];
                }
                minVal = min(minVal, arr2[l2]);
                l2 += 2;
            }
        }
        return ans;
    }
};
